        if not records:
            return None

        # Determine the end of the window from the latest timestamp recorded for this metric.
        max_ts = max(ts for ts, val in records)
        start_ts = max_ts - window_sec

        # Collect all values within the window [start_ts, max_ts]
        window_values = [val for ts, val in records if start_ts <= ts <= max_ts]

        if not window_values:
            return None

        # If agg_func is provided as a string, map it to the corresponding operation
        if isinstance(agg_func, str):
            func_name = agg_func.lower()
            if func_name in ('avg', 'mean'):
                return sum(window_values) / len(window_values)
            elif func_name == 'sum':
                return sum(window_values)
            elif func_name == 'min':
                return min(window_values)
            elif func_name == 'max':
                return max(window_values)
            elif func_name == 'count':
                return len(window_values)
            else:
                raise ValueError(f"Unsupported aggregation function name: {agg_func}")

